// src/RegisterPage.js
import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import apiClient from "./api/apiClient";
import logo from "./assets/login/logo.png";

export default function RegisterPage() {
  const [role, setRole] = useState("deportista");
  const [deportistaForm, setDeportistaForm] = useState({
    nombreCompleto: "",
    cedula: "",
    email: "",
    telefono: "",
    fechaNacimiento: "",
    genero: "",
    ciudad: "",
    deportes: {
      futbol: false,
      tenis: false,
      basquet: false,
      voley: false,
      padel: false,
      futsal: false,
    },
    password: "",
    passwordConfirm: "",
  });

  const [adminForm, setAdminForm] = useState({
    nombreComplejo: "",
    nit: "",
    direccion: "",
    ciudad: "",
    email: "",
    sitioWeb: "",
    telefono1: "",
    telefono2: "",
    descripcion: "",
    horaApertura: "",
    horaCierre: "",
    diasOperacion: "",
    numeroCanchas: "",
    deportes: {
      futbol: false,
      tenis: false,
      basquet: false,
      voley: false,
      padel: false,
      futsal: false,
      badminton: false,
      pingpong: false,
    },
    password: "",
    passwordConfirm: "",
  });

  const [aceptaTerminos, setAceptaTerminos] = useState(false);
  const [cargando, setCargando] = useState(false);
  const [error, setError] = useState("");
  const [exito, setExito] = useState("");
  const navigate = useNavigate();

  // --- handlers genéricos ---

  const handleChangeDeportista = (field, value) => {
    setDeportistaForm((prev) => ({ ...prev, [field]: value }));
  };

  const handleChangeAdmin = (field, value) => {
    setAdminForm((prev) => ({ ...prev, [field]: value }));
  };

  const handleCheckboxDeportista = (sport) => {
    setDeportistaForm((prev) => ({
      ...prev,
      deportes: { ...prev.deportes, [sport]: !prev.deportes[sport] },
    }));
  };

  const handleCheckboxAdmin = (sport) => {
    setAdminForm((prev) => ({
      ...prev,
      deportes: { ...prev.deportes, [sport]: !prev.deportes[sport] },
    }));
  };

  // --- submit ---

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setExito("");

    if (!aceptaTerminos) {
      setError("Debes aceptar los términos y condiciones.");
      return;
    }

    try {
      setCargando(true);

      if (role === "deportista") {
        const {
          nombreCompleto,
          cedula,
          email,
          telefono,
          password,
          passwordConfirm,
        } = deportistaForm;

        if (
          !nombreCompleto ||
          !cedula ||
          !email ||
          !telefono ||
          !password ||
          !passwordConfirm
        ) {
          setError("Por favor completa todos los campos obligatorios (*).");
          setCargando(false);
          return;
        }

        if (password !== passwordConfirm) {
          setError("Las contraseñas no coinciden.");
          setCargando(false);
          return;
        }

        // separar nombre y apellido para el backend
        const partesNombre = nombreCompleto.trim().split(" ");
        const nombre = partesNombre.shift() || "";
        const apellido = partesNombre.join(" ") || "-";

        // Endpoint del backend (según colección de Postman)
        const payload = {
          email,
          password,
          password_confirm: passwordConfirm,
          nombre,
          apellido,
          documento_identidad: cedula,
          telefono,
        };

        await apiClient.post("/accounts/deportistas/", payload);

        setExito("Cuenta de deportista creada correctamente.");
        // redirige al login
        setTimeout(() => navigate("/login"), 1200);
      } else {
        // ADMIN / CLUB
        const {
          nombreComplejo,
          nit,
          direccion,
          ciudad,
          email,
          telefono1,
          telefono2,
          descripcion,
          horaApertura,
          horaCierre,
          diasOperacion,
          numeroCanchas,
          password,
          passwordConfirm,
        } = adminForm;

        if (
          !nombreComplejo ||
          !nit ||
          !direccion ||
          !email ||
          !telefono1 ||
          !password ||
          !passwordConfirm
        ) {
          setError("Por favor completa todos los campos obligatorios (*).");
          setCargando(false);
          return;
        }

        if (password !== passwordConfirm) {
          setError("Las contraseñas no coinciden.");
          setCargando(false);
          return;
        }

        // construir texto de disponibilidad combinando horario + días
        const disponibilidad = diasOperacion
          ? `${diasOperacion} ${horaApertura || ""} - ${horaCierre || ""}`.trim()
          : "";

        // OJO: departamento y ciudad son IDs numéricos en el back.
        // Mientras no tengas el selector conectado, usamos 1 como ejemplo.
        const payload = {
          email,
          password,
          password_confirm: passwordConfirm,
          nombre: nombreComplejo,
          nit,
          direccion,
          telefono_1: telefono1,
          telefono_2: telefono2 || "",
          departamento: 1,
          ciudad: 1,
          disponibilidad,
          informacion: descripcion,
        };

        await apiClient.post("/accounts/clubes/", payload);

        setExito("Complejo registrado correctamente.");
        setTimeout(() => navigate("/login"), 1200);
      }
    } catch (err) {
      console.error(err);
      const msg =
        err.response?.data?.detail ||
        err.response?.data?.error ||
        "Ocurrió un error al registrar. Revisa los datos o intenta más tarde.";
      setError(msg);
    } finally {
      setCargando(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-green-50 flex flex-col items-center">
      {/* NAVBAR */}
      <nav className="w-full flex items-center gap-2 px-10 py-4">
        <img src={logo} alt="logo" className="w-7 h-7" />
        <span className="font-bold text-xl text-blue-700">CanchaYa</span>
      </nav>

      {/* CONTENIDO PRINCIPAL */}
      <div className="w-full flex justify-center mt-4 mb-10">
        <div className="bg-white w-[950px] rounded-3xl shadow-xl border border-gray-100 p-10">
          {/* VOLVER */}
          <div className="flex items-center gap-2 text-slate-600 text-sm mb-4 cursor-pointer">
            <span className="text-xl">←</span>
            <Link to="/" className="hover:underline">
              Volver al inicio
            </Link>
          </div>

          {/* TÍTULO */}
          <h2 className="text-2xl font-semibold text-center text-slate-900">
            Crear Cuenta
          </h2>
          <p className="text-center text-gray-500 mb-6">
            Únete a CanchaYa y comienza a disfrutar del deporte
          </p>

          {/* SELECTOR DE ROL */}
          <div className="bg-gray-100 rounded-full p-1 flex mb-6">
            <button
              className={`flex-1 py-2 text-sm font-semibold rounded-full ${
                role === "deportista"
                  ? "bg-white shadow text-slate-900"
                  : "text-gray-500"
              }`}
              onClick={() => setRole("deportista")}
              type="button"
            >
              Deportista
            </button>

            <button
              className={`flex-1 py-2 text-sm font-semibold rounded-full ${
                role === "admin"
                  ? "bg-white shadow text-slate-900"
                  : "text-gray-500"
              }`}
              onClick={() => setRole("admin")}
              type="button"
            >
              Administrador
            </button>
          </div>

          {/* SUBTÍTULO */}
          <h3 className="font-semibold text-slate-900 text-center">
            {role === "deportista"
              ? "Registro para Deportistas"
              : "Registro para Administradores"}
          </h3>

          <p className="text-gray-500 text-center text-sm mb-8">
            {role === "deportista"
              ? "Crea tu cuenta para buscar y reservar canchas deportivas"
              : "Registra tu complejo deportivo en CanchaYa"}
          </p>

          {/* MENSAJES */}
          {error && (
            <div className="mb-4 text-sm text-red-600 bg-red-50 border border-red-200 px-4 py-2 rounded-lg">
              {error}
            </div>
          )}
          {exito && (
            <div className="mb-4 text-sm text-green-700 bg-green-50 border border-green-200 px-4 py-2 rounded-lg">
              {exito}
            </div>
          )}

          {/* FORMULARIO */}
          <form className="flex flex-col gap-6" onSubmit={handleSubmit}>
            {/* FORMULARIO DEPORTISTAS */}
            {role === "deportista" && (
              <>
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Nombre completo *
                    </label>
                    <input
                      type="text"
                      placeholder="Ej: Juan Pérez"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.nombreCompleto}
                      onChange={(e) =>
                        handleChangeDeportista("nombreCompleto", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Cédula de ciudadanía *
                    </label>
                    <input
                      type="text"
                      placeholder="Ej: 12345678"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.cedula}
                      onChange={(e) =>
                        handleChangeDeportista("cedula", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Email *
                    </label>
                    <input
                      type="email"
                      placeholder="tu-email@ejemplo.com"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.email}
                      onChange={(e) =>
                        handleChangeDeportista("email", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Teléfono *
                    </label>
                    <input
                      type="text"
                      placeholder="+57 300 123 4567"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.telefono}
                      onChange={(e) =>
                        handleChangeDeportista("telefono", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Fecha de nacimiento *
                    </label>
                    <input
                      type="date"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.fechaNacimiento}
                      onChange={(e) =>
                        handleChangeDeportista(
                          "fechaNacimiento",
                          e.target.value
                        )
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Género *
                    </label>
                    <select
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.genero}
                      onChange={(e) =>
                        handleChangeDeportista("genero", e.target.value)
                      }
                    >
                      <option value="">Seleccionar</option>
                      <option value="M">Masculino</option>
                      <option value="F">Femenino</option>
                      <option value="O">Otro</option>
                    </select>
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Ciudad
                    </label>
                    <select
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.ciudad}
                      onChange={(e) =>
                        handleChangeDeportista("ciudad", e.target.value)
                      }
                    >
                      <option value="">Selecciona tu ciudad</option>
                    </select>
                  </div>
                </div>

                {/* DEPORTES */}
                <div>
                  <label className="text-sm font-medium text-slate-700">
                    Deportes de interés *
                  </label>
                  <div className="grid grid-cols-3 gap-2 text-sm mt-2">
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={deportistaForm.deportes.futbol}
                        onChange={() => handleCheckboxDeportista("futbol")}
                      />
                      Fútbol
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={deportistaForm.deportes.tenis}
                        onChange={() => handleCheckboxDeportista("tenis")}
                      />
                      Tenis
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={deportistaForm.deportes.basquet}
                        onChange={() => handleCheckboxDeportista("basquet")}
                      />
                      Básquet
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={deportistaForm.deportes.voley}
                        onChange={() => handleCheckboxDeportista("voley")}
                      />
                      Vóley
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={deportistaForm.deportes.padel}
                        onChange={() => handleCheckboxDeportista("padel")}
                      />
                      Pádel
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={deportistaForm.deportes.futsal}
                        onChange={() => handleCheckboxDeportista("futsal")}
                      />
                      Futsal
                    </label>
                  </div>
                </div>

                {/* CONTRASEÑAS */}
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Contraseña *
                    </label>
                    <input
                      type="password"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.password}
                      onChange={(e) =>
                        handleChangeDeportista("password", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Confirmar contraseña *
                    </label>
                    <input
                      type="password"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={deportistaForm.passwordConfirm}
                      onChange={(e) =>
                        handleChangeDeportista(
                          "passwordConfirm",
                          e.target.value
                        )
                      }
                    />
                  </div>
                </div>
              </>
            )}

            {/* FORMULARIO ADMINISTRADORES */}
            {role === "admin" && (
              <>
                <h3 className="font-semibold text-slate-900">
                  Información del Club
                </h3>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Nombre del complejo *
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.nombreComplejo}
                      onChange={(e) =>
                        handleChangeAdmin("nombreComplejo", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      NIT *
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.nit}
                      onChange={(e) =>
                        handleChangeAdmin("nit", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Dirección completa *
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.direccion}
                      onChange={(e) =>
                        handleChangeAdmin("direccion", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Ciudad *
                    </label>
                    <select
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.ciudad}
                      onChange={(e) =>
                        handleChangeAdmin("ciudad", e.target.value)
                      }
                    >
                      <option value="">Selecciona la ciudad</option>
                    </select>
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Email del complejo *
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.email}
                      onChange={(e) =>
                        handleChangeAdmin("email", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Sitio web (opcional)
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.sitioWeb}
                      onChange={(e) =>
                        handleChangeAdmin("sitioWeb", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Teléfonos de contacto *
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.telefono1}
                      onChange={(e) =>
                        handleChangeAdmin("telefono1", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Teléfono adicional
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.telefono2}
                      onChange={(e) =>
                        handleChangeAdmin("telefono2", e.target.value)
                      }
                    />
                  </div>
                </div>

                <div>
                  <label className="text-sm font-medium text-slate-700">
                    Descripción del complejo
                  </label>
                  <textarea
                    className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                    value={adminForm.descripcion}
                    onChange={(e) =>
                      handleChangeAdmin("descripcion", e.target.value)
                    }
                  />
                </div>

                {/* INFO OPERATIVA */}
                <h3 className="font-semibold text-slate-900 mt-4">
                  Información Operativa
                </h3>

                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Horario de apertura *
                    </label>
                    <input
                      type="time"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.horaApertura}
                      onChange={(e) =>
                        handleChangeAdmin("horaApertura", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Horario de cierre *
                    </label>
                    <input
                      type="time"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.horaCierre}
                      onChange={(e) =>
                        handleChangeAdmin("horaCierre", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Días de operación *
                    </label>
                    <select
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.diasOperacion}
                      onChange={(e) =>
                        handleChangeAdmin("diasOperacion", e.target.value)
                      }
                    >
                      <option value="">Seleccionar</option>
                      <option value="Lunes a Viernes">Lunes a Viernes</option>
                      <option value="Lunes a Sábado">Lunes a Sábado</option>
                      <option value="Todos los días">Todos los días</option>
                    </select>
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Número de canchas *
                    </label>
                    <input
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.numeroCanchas}
                      onChange={(e) =>
                        handleChangeAdmin("numeroCanchas", e.target.value)
                      }
                    />
                  </div>
                </div>

                <div>
                  <label className="text-sm font-medium text-slate-700">
                    Deportes disponibles *
                  </label>
                  <div className="grid grid-cols-3 gap-2 text-sm mt-2">
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.futbol}
                        onChange={() => handleCheckboxAdmin("futbol")}
                      />
                      Fútbol
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.tenis}
                        onChange={() => handleCheckboxAdmin("tenis")}
                      />
                      Tenis
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.basquet}
                        onChange={() => handleCheckboxAdmin("basquet")}
                      />
                      Básquet
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.voley}
                        onChange={() => handleCheckboxAdmin("voley")}
                      />
                      Vóley
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.padel}
                        onChange={() => handleCheckboxAdmin("padel")}
                      />
                      Pádel
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.futsal}
                        onChange={() => handleCheckboxAdmin("futsal")}
                      />
                      Futsal
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.badminton}
                        onChange={() => handleCheckboxAdmin("badminton")}
                      />
                      Bádminton
                    </label>
                    <label>
                      <input
                        type="checkbox"
                        className="mr-1"
                        checked={adminForm.deportes.pingpong}
                        onChange={() => handleCheckboxAdmin("pingpong")}
                      />
                      Ping Pong
                    </label>
                  </div>
                </div>

                {/* CONTRASEÑAS */}
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Contraseña *
                    </label>
                    <input
                      type="password"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.password}
                      onChange={(e) =>
                        handleChangeAdmin("password", e.target.value)
                      }
                    />
                  </div>

                  <div>
                    <label className="text-sm font-medium text-slate-700">
                      Confirmar contraseña *
                    </label>
                    <input
                      type="password"
                      className="w-full mt-1 p-3 rounded-lg border bg-gray-50 text-sm"
                      value={adminForm.passwordConfirm}
                      onChange={(e) =>
                        handleChangeAdmin("passwordConfirm", e.target.value)
                      }
                    />
                  </div>
                </div>
              </>
            )}

            {/* TÉRMINOS */}
            <div className="flex items-center gap-2 text-sm">
              <input
                type="checkbox"
                checked={aceptaTerminos}
                onChange={(e) => setAceptaTerminos(e.target.checked)}
              />
              <span>
                Acepto los términos y condiciones y las políticas de privacidad
              </span>
            </div>

            {/* BOTÓN PRINCIPAL */}
            <button
              type="submit"
              disabled={cargando}
              className="bg-slate-900 text-white py-3 rounded-xl font-semibold text-sm hover:bg-black disabled:opacity-60"
            >
              {cargando
                ? "Procesando..."
                : role === "deportista"
                ? "Crear Cuenta"
                : "Registrar Complejo"}
            </button>

            {/* ENLACE A LOGIN */}
            <p className="text-center text-gray-500 text-sm mt-2">
              ¿Ya tienes una cuenta?{" "}
              <Link
                to="/login"
                className="text-slate-900 font-semibold hover:underline"
              >
                Inicia sesión aquí
              </Link>
            </p>
          </form>
        </div>
      </div>
    </div>
  );
}
